test('invoiceTotals sums multiple lines', () => {
  const invoice = {
    customerId: 'C-001',
    issueDate: '2025-10-07',
    status: 'draft',
    lines: [
      {
        sku: 'DES-HOUR',
        name: 'Design work (hour)',
        qty: 5,
        unitPrice: 8500,
        vatRate: 21,
        discountPercent: 0,
      },
      {
        sku: 'DEV-HOUR',
        name: 'Development (hour)',
        qty: 3,
        unitPrice: 9500,
        vatRate: 21,
        discountPercent: 0,
      },
    ],
  };
  const totals = invoiceTotals(invoice);
  const vat = Math.round(42500 * 0.21) + Math.round(28500 * 0.21);
  assert.deepEqual(totals, { subtotal: 71000, discount: 0, vat, voucher: 0, total: 71000 + vat });
});

